CREATE FUNCTION public.prepare_task_nft_checkout(_user uuid,_listing uuid,_rate numeric) RETURNS json LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l record; o record; ref text; reward numeric; BEGIN IF _user IS NULL OR _rate IS NULL OR _rate<=0 THEN RAISE EXCEPTION 'Invalid checkout'; END IF; SELECT * INTO l FROM public.task_nft_listings WHERE id=_listing AND status='open' FOR UPDATE; IF l.id IS NULL OR l.seller_id=_user THEN RAISE EXCEPTION 'Listing unavailable'; END IF; IF EXISTS(SELECT 1 FROM public.profiles WHERE id IN (_user,l.seller_id) AND marketplace_blocked) THEN RAISE EXCEPTION 'Marketplace access suspended'; END IF; SELECT * INTO o FROM public.task_nft_instances WHERE id=l.instance_id FOR UPDATE; IF o.user_id IS DISTINCT FROM l.seller_id OR NOT EXISTS(SELECT 1 FROM public.nfts WHERE id=l.nft_id AND active AND mining_plan_id IS NULL) THEN RAISE EXCEPTION 'NFT unavailable'; END IF; IF EXISTS(SELECT 1 FROM public.task_nft_orders WHERE listing_id=l.id AND status='pending' AND expires_at>now()) THEN RAISE EXCEPTION 'NFT reserved by another checkout'; END IF; SELECT round(l.price_usd/5*task_sale_mvg_per_five_usd,8) INTO reward FROM public.settings WHERE id=1; ref:='TASK-'||upper(replace(gen_random_uuid()::text,'-','')); INSERT INTO public.task_nft_orders(listing_id,user_id,seller_id,reference,amount_usd,amount_ngn_kobo,mining_mvg) VALUES(l.id,_user,l.seller_id,ref,l.price_usd,round(l.price_usd*_rate*100),reward); RETURN json_build_object('reference',ref,'kobo',round(l.price_usd*_rate*100),'usd',l.price_usd); END $$;
CREATE FUNCTION public.fulfill_task_nft_payment(_reference text,_paid_kobo bigint) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p record; l record; o record; BEGIN SELECT * INTO p FROM public.task_nft_orders WHERE reference=_reference FOR UPDATE; IF p.id IS NULL THEN RETURN 'not_found'; END IF; IF p.status='success' THEN RETURN 'already'; END IF; IF p.status='needs_review' THEN RETURN 'needs_review'; END IF; IF _paid_kobo<>p.amount_ngn_kobo THEN UPDATE public.task_nft_orders SET status='needs_review',verified_at=now() WHERE id=p.id; RETURN 'amount_mismatch'; END IF; SELECT * INTO l FROM public.task_nft_listings WHERE id=p.listing_id FOR UPDATE; SELECT * INTO o FROM public.task_nft_instances WHERE id=l.instance_id FOR UPDATE; IF l.status<>'open' OR o.user_id IS DISTINCT FROM p.seller_id OR NOT EXISTS(SELECT 1 FROM public.nfts WHERE id=l.nft_id AND active AND mining_plan_id IS NULL) OR EXISTS(SELECT 1 FROM public.profiles WHERE id IN(p.user_id,p.seller_id) AND marketplace_blocked) THEN UPDATE public.task_nft_orders SET status='needs_review',verified_at=now() WHERE id=p.id; RETURN 'needs_review'; END IF; UPDATE public.task_nft_instances SET user_id=p.user_id WHERE id=o.id; UPDATE public.task_nft_listings SET status='sold',buyer_id=p.user_id,sold_at=now() WHERE id=l.id; INSERT INTO public.ledger_entries(user_id,account,amount,kind,reference,details) VALUES(p.seller_id,'referral',p.amount_usd,'task_nft_sale','TASK-PROCEEDS-'||p.reference,jsonb_build_object('listing_id',l.id,'usd',p.amount_usd)); IF p.mining_mvg>0 THEN INSERT INTO public.ledger_entries(user_id,account,amount,kind,status,reference,details) VALUES(p.seller_id,'mvt',p.mining_mvg,'task_nft_sale_reward','pending','TASK-REWARD-'||p.reference,jsonb_build_object('listing_id',l.id,'usd',p.amount_usd,'locked',true)); END IF; UPDATE public.task_nft_orders SET status='success',verified_at=now() WHERE id=p.id; INSERT INTO public.notifications(user_id,title,body) VALUES(p.seller_id,'Task NFT sold','$'||p.amount_usd||' sale proceeds and '||p.mining_mvg||' locked mining MVG credited.'); RETURN 'ok'; END $$;
REVOKE ALL ON FUNCTION public.prepare_task_nft_checkout(uuid,uuid,numeric),public.fulfill_task_nft_payment(text,bigint) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.prepare_task_nft_checkout(uuid,uuid,numeric),public.fulfill_task_nft_payment(text,bigint) TO service_role;